 bool Painted(){if(host==null||!host.inputRouter.Ready)return false;var texture=host.browser.browserClient.BrowserTexture;int bright=0;for(int x=1;x<9;x++)for(int y=1;y<9;y++){var color=texture.GetPixel(texture.width*x/10,texture.height*y/10);if(Mathf.Max(color.r,color.g,color.b)>.12f)bright++;}return bright>3;}
